import { getSupabaseAdmin } from "./supabase";
import { isAdminEmail } from "./auth";

// The devis interne generated by the expertise IA (before any entreprise is
// involved) needs a real owner in the `quotes` table's user_id column — it
// belongs to Amira until an entreprise picks up the offer, since she's the
// one alerted and able to correct it. Resolves her real Supabase Auth id by
// email via the service-role client (no RLS token exists for this yet).
// Intentionally always Amira specifically (not "any admin") — a single
// fixed owner, not an admin-privilege check; see isVerifiedUserAdmin below
// for that.
const PRIMARY_ADMIN_EMAIL = "bouhouchimira@gmail.com";

let cachedAdminUserId = "";

export async function resolveAdminUserId() {
  if (cachedAdminUserId) return cachedAdminUserId;
  const { data, error } = await getSupabaseAdmin()
    .from("users")
    .select("id")
    .eq("email", PRIMARY_ADMIN_EMAIL)
    .maybeSingle();
  if (error || !data?.id) return "";
  cachedAdminUserId = data.id;
  return cachedAdminUserId;
}

// Real "is this verified entreprise user one of the 2 admin accounts"
// check. Entreprise accounts live only in Supabase Auth's `users` table
// (created via auth.signUp, see app/api/auth/signup/route.js) — never in
// the local JSON db.users array, which lib/particulier-users.js documents
// as dedicated to particulier accounts only. So looking up `isAdmin` on
// db.users (as lib/db.js's old applyAdminBypass and app/api/ouvrages/
// route.js's resolveCaller used to) never finds an entreprise admin and
// always resolves to false — this is the only check that actually works,
// by resolving the verified id's real email and checking it against
// lib/auth.js's ADMIN_EMAILS.
export async function isVerifiedUserAdmin(userId) {
  if (!userId) return false;
  const { data, error } = await getSupabaseAdmin().from("users").select("email").eq("id", userId).maybeSingle();
  if (error || !data?.email) return false;
  return isAdminEmail(data.email);
}

export { PRIMARY_ADMIN_EMAIL };
